class Solution {
    bool rotationMatches(const vector<int>& a, const vector<int>& b, int l, int k) {
        vector<int> pi(k, 0);
        for (int i = 1; i < k; ++i) {
            int j = pi[i - 1];
            while (j && b[l + i] != b[l + j]) j = pi[j - 1];
            if (b[l + i] == b[l + j]) ++j;
            pi[i] = j;
        }
        int j = 0;
        for (int i = 0; i < 2 * k - 1; ++i) {
            int x = a[l + i % k];
            while (j && x != b[l + j]) j = pi[j - 1];
            if (x == b[l + j]) ++j;
            if (j == k) return true;
        }
        return false;
    }
public:
    int sortableIntegers(vector<int>& nums) {
        int n = nums.size(), answer = 0;
        vector<int> sorted = nums;
        sort(sorted.begin(), sorted.end());
        for (int k = 1; k <= n; ++k) if (n % k == 0) {
            bool ok = true;
            for (int l = 0; l < n; l += k) {
                if (!rotationMatches(nums, sorted, l, k)) {
                    ok = false;
                    break;
                }
            }
            if (ok) answer += k;
        }
        return answer;
    }
};
